import{_ as e,o as d,c as l,a5 as a}from"./chunks/framework.CXroN2RO.js";const g=JSON.parse('{"title":"低レイヤからゲームの仕組みを学ぶ","description":"","frontmatter":{"title":"低レイヤからゲームの仕組みを学ぶ","study":{"source":"IT教本","status":"published","summary":"入力から画面表示までを、情報表現・CPU・メモリ・OS・言語・GPUの順にたどる学習コースです。各章は学ぶ範囲、短い概説、演習、参考資料をまとめた学習計画・概要です。章を読むだけで、各分野の詳解や実装検証まで済むものではありません。下の章順は学習の目安で、疑問がある章から入っても構いません。","section":"learning","format":"index","domain":"game","collection":"low-level","order":0}},"headers":[],"relativePath":"guide/low-level/index.md","filePath":"guide/low-level/index.md"}'),r={name:"guide/low-level/index.md"};function i(o,t,n,h,s,u){return d(),l("div",null,[...t[0]||(t[0]=[a('<div id="ゲームプログラマのための完全理解教本" class="study-legacy-anchor" aria-hidden="true"></div><h1 id="低レイヤからゲームの仕組みを学ぶ" tabindex="-1">低レイヤからゲームの仕組みを学ぶ <a class="header-anchor" href="#低レイヤからゲームの仕組みを学ぶ" aria-label="Permalink to &quot;低レイヤからゲームの仕組みを学ぶ&quot;">​</a></h1><h2 id="このページで案内すること" tabindex="-1">このページで案内すること <a class="header-anchor" href="#このページで案内すること" aria-label="Permalink to &quot;このページで案内すること&quot;">​</a></h2><p>入力から画面表示までを、情報表現・CPU・メモリ・OS・言語・GPUの順にたどる学習コースです。各章は学ぶ範囲、短い概説、演習、参考資料をまとめた<strong>学習計画・概要</strong>です。章を読むだけで、各分野の詳解や実装検証まで済むものではありません。下の章順は学習の目安で、疑問がある章から入っても構いません。</p><h2 id="関連する辞典本文・実践" tabindex="-1">関連する辞典本文・実践 <a class="header-anchor" href="#関連する辞典本文・実践" aria-label="Permalink to &quot;関連する辞典本文・実践&quot;">​</a></h2><ul><li><a href="/study/runtime/cpp-internals/build-pipeline-journey.html">ソースコードからCPU命令まで</a>と<a href="/study/runtime/memory/allocators-and-pools.html">アロケータ</a>で、個別の仕組みを調べられます。</li><li><a href="/study/game/ecs.html">ECS</a>ではデータと更新の構成、<a href="/study/game/shooter-design.html">小さなシューティング</a>では動く実装へのつなぎ方を扱います。</li></ul><p>情報表現、C、アセンブリ、OSなどは、このコースの概説が中心で、専用の辞典本文がまだ揃っていません。各章の冒頭に、既存本文へのリンクと未整備の範囲を示します。</p><h2 id="入力から表示までを学ぶ" tabindex="-1">入力から表示までを学ぶ <a class="header-anchor" href="#入力から表示までを学ぶ" aria-label="Permalink to &quot;入力から表示までを学ぶ&quot;">​</a></h2><p>対象読者: エンジンを使った経験があり、その下で何が起きているかを調べたい人。 実装や資料の読解を通じ、ゲームが動く仕組みを段階的に理解するための学習案です。</p><hr><h2 id="目次" tabindex="-1">目次 <a class="header-anchor" href="#目次" aria-label="Permalink to &quot;目次&quot;">​</a></h2><table tabindex="0"><thead><tr><th>章</th><th>学習案内</th><th>テーマ</th></tr></thead><tbody><tr><td>第0章</td><td><a href="/study/guide/low-level/learning-map.html">学習全体マップ</a></td><td>全体像・学習戦略・環境構築</td></tr><tr><td>第1章</td><td><a href="/study/guide/low-level/computer-and-data.html">コンピュータと情報の表現</a></td><td>情報の表現・2進数・ノイマン型</td></tr><tr><td>第2章</td><td><a href="/study/guide/low-level/electricity-cpu-instructions.html">論理回路・CPU・命令</a></td><td>論理回路→CPU→命令セット</td></tr><tr><td>第3章</td><td><a href="/study/guide/low-level/memory-and-cache.html">メモリ階層とキャッシュ</a></td><td>メモリ階層・キャッシュ・データ指向の土台</td></tr><tr><td>第4章</td><td><a href="/study/guide/low-level/assembly.html">アセンブリと逆アセンブリ</a></td><td>x64アセンブリ・VSで逆アセンブリを読む</td></tr><tr><td>第5章</td><td><a href="/study/guide/low-level/c-language.html">C言語とメモリ</a></td><td>メモリと機械語への接続</td></tr><tr><td>第6章</td><td><a href="/study/guide/low-level/pointers-and-memory.html">ポインタとメモリ管理</a></td><td>ポインタ・記憶域・アロケータ</td></tr><tr><td>第7章</td><td><a href="/study/guide/low-level/compiler-linker-executable.html">コンパイラ・リンカ・実行ファイル・ABI</a></td><td>コンパイラ・リンカ・ELF/PE・ABI</td></tr><tr><td>第8章</td><td><a href="/study/guide/low-level/operating-system.html">OSの仕組み</a></td><td>プロセス・スレッド・仮想メモリ・システムコール</td></tr><tr><td>第9章</td><td><a href="/study/guide/low-level/cpp-language.html">C++の型・寿命・実行</a></td><td>C++ ── ゲーム業界の母語</td></tr><tr><td>第10章</td><td><a href="/study/guide/low-level/algorithms-and-game-math.html">データ構造・アルゴリズム・ゲーム数学</a></td><td>ゲームに効くDS/Algo・線形代数</td></tr><tr><td>第11章</td><td><a href="/study/guide/low-level/gpu-architecture.html">GPUアーキテクチャ</a></td><td>並列実行とメモリ階層</td></tr><tr><td>第12章</td><td><a href="/study/guide/low-level/rendering-pipeline-shaders.html">レンダリングパイプラインとシェーダ</a></td><td>頂点からピクセルまで</td></tr><tr><td>第13章</td><td><a href="/study/guide/low-level/graphics-apis.html">グラフィックスAPI</a></td><td>OpenGL / DirectX 12 / Vulkan</td></tr><tr><td>第14章</td><td><a href="/study/guide/low-level/input-and-game-loop.html">入力とゲームループ</a></td><td>パッド入力の旅・時間・フレーム</td></tr><tr><td>第15章</td><td><a href="/study/guide/low-level/engine-architecture-ecs.html">ゲームエンジンの構成とECS</a></td><td>エンジンの解剖学・ECS</td></tr><tr><td>第16章</td><td><a href="/study/guide/low-level/unity-internals.html">Unityの内部を調べる</a></td><td>C#/IL2CPP/DOTS・資料と計測で調べる</td></tr><tr><td>第17章</td><td><a href="/study/guide/low-level/unreal-internals.html">Unreal Engineのソースを読む</a></td><td>UE5ソースコードリーディング</td></tr><tr><td>第18章</td><td><a href="/study/guide/low-level/debugging-and-profiling.html">デバッグとプロファイリング</a></td><td>VS・RenderDoc・PIX・Tracy</td></tr><tr><td>最終章</td><td><a href="/study/guide/low-level/button-to-screen.html">ボタンを押してから画面に出るまで</a></td><td>全章統合 ── 入力から表示まで</td></tr><tr><td>発展章</td><td><a href="/study/guide/low-level/advanced-topics.html">専門テーマを選ぶ</a></td><td>目的に応じて選ぶ専門テーマ</td></tr></tbody></table><hr><h2 id="この教本の設計思想" tabindex="-1">この教本の設計思想 <a class="header-anchor" href="#この教本の設計思想" aria-label="Permalink to &quot;この教本の設計思想&quot;">​</a></h2><ol><li><p><strong>下から上へ、ただしゲームに必要な最短経路で。</strong> 電子回路の物理やチューリングマシンの証明のような「教養としては面白いが ゲーム開発に直結しない寄り道」は最小限にし、CPU・メモリ・OS・GPUという 「ゲームが実際に走る場所」に紙面を集中させる。</p></li><li><p><strong>すべての章が最終章(1フレームの旅)への伏線。</strong> 各章末の図で「今学んだことがフレームのどこで使われるか」を必ず示す。</p></li><li><p><strong>読む・書く・覗くの三本柱。</strong> 本を読むだけでは理解にならない。各章で必ず (a) コードを書き、 (b) OSSのソースを読み、(c) デバッガ/プロファイラで実物を覗く。</p></li></ol><hr><h2 id="このコースで目指すこと" tabindex="-1">このコースで目指すこと <a class="header-anchor" href="#このコースで目指すこと" aria-label="Permalink to &quot;このコースで目指すこと&quot;">​</a></h2><p>以下は、関連本文や参考資料を読み、演習・実装・計測を重ねて目指す到達点です。 このコースの概説を読むだけで、すべてを習得できるという意味ではありません。</p><h3 id="具体的なスキル" tabindex="-1">具体的なスキル <a class="header-anchor" href="#具体的なスキル" aria-label="Permalink to &quot;具体的なスキル&quot;">​</a></h3><ul><li><strong>UE5のソースコードが読める</strong>: <code>FEngineLoop::Tick()</code> から <code>RHICmdList</code> 経由で D3D12/Vulkanのコマンド発行までコールスタックを追い、UObject/GC/リフレクションの 仕組みを説明できる。</li><li><strong>Unityの仕組みを資料と計測で調べる</strong>: <code>GetComponent</code>のコスト要因や、IL2CPPの 変換経路、DOTSのデータ配置を調べる。公開された仕様、説明モデル、実測を区別する。</li><li><strong>RenderDocでGPUを追える</strong>: 1フレームをキャプチャして、ドローコール単位で 頂点入力→VS→ラスタライズ→PS→出力マージャを検査し、描画バグの原因 (ステート設定ミス、UV反転、深度テスト失敗など)を特定できる。</li><li><strong>Visual Studioでアセンブリまで追える</strong>: 逆アセンブリウィンドウでC++コードと 機械語の対応を読み、レジスタ・コールスタック・メモリウィンドウで クラッシュダンプの原因(ダングリングポインタ、スタック破壊等)を解析できる。</li><li><strong>ゲームエンジンを簡易実装できる</strong>: プラットフォーム層(ウィンドウ・入力)、 レンダラ(D3D12 or Vulkan or OpenGL)、リソース管理、ゲームループ、ECS、 簡易物理を備えた2D/3Dエンジンをゼロから書ける。</li><li><strong>AIが生成したコードをレビューできる</strong>: 「動くけど毎フレームヒープ確保している」 「このshared_ptrは循環参照する」「このループはキャッシュミスだらけ」といった、 表面的には正しいが性能・安全性に問題のあるコードを見抜ける。</li></ul><h3 id="思考レベルの変化" tabindex="-1">思考レベルの変化 <a class="header-anchor" href="#思考レベルの変化" aria-label="Permalink to &quot;思考レベルの変化&quot;">​</a></h3><ul><li>パフォーマンス問題を前に「なんとなく重い」ではなく 「CPUバウンドかGPUバウンドか → どのパスか → キャッシュか分岐かALUか」と 計測に基づいて系統的に切り分けられる。</li><li>クラッシュを前に「再起動して祈る」ではなく、ダンプとレジスタと メモリレイアウトから原因を論理的に特定できる。</li><li>新しいエンジン・API・言語に出会ったとき、既知の仕組みとの共通点と違いを探し、 調べるべき仕様や計測対象を選べるようにする。</li></ul><hr><h2 id="推奨学習ペース-目安" tabindex="-1">推奨学習ペース(目安) <a class="header-anchor" href="#推奨学習ペース-目安" aria-label="Permalink to &quot;推奨学習ペース(目安)&quot;">​</a></h2><p>働きながらの場合、<strong>全体で18〜30ヶ月</strong>を想定。焦らないこと。</p><ul><li>第1〜4章(ハードウェア・アセンブリ): 2〜3ヶ月</li><li>第5〜7章(C・ポインタ・コンパイラ/リンカ): 3〜4ヶ月</li><li>第8章(OS): 2〜3ヶ月</li><li>第9〜10章(C++・DS/Algo/数学): 3〜4ヶ月</li><li>第11〜13章(GPU・レンダリング・API): 3〜5ヶ月</li><li>第14〜15章(ゲームループ・エンジン/ECS): 2〜3ヶ月(自作エンジン開始)</li><li>第16〜18章(Unity/UE内部・デバッグ): 3〜4ヶ月</li><li>最終章・発展編: 継続的に</li></ul><p>「1章を100%理解してから次へ」ではなく、<strong>70%で先に進み、後の章で戻ってくる</strong> 螺旋型を推奨する。後の章が前の章の最高の復習になるよう設計してある。</p>',27)])])}const m=e(r,[["render",i]]);export{g as __pageData,m as default};
